-- -----------------------------------------------------------------------------
-- Integrity rules Prisma cannot express.
-- -----------------------------------------------------------------------------
-- One group-root theme per tenant (property_id NULL escapes the composite unique).
CREATE UNIQUE INDEX "site_themes_one_group_root" ON "site_themes" ("tenant_id") WHERE "property_id" IS NULL;
ALTER TABLE "site_themes" ADD CONSTRAINT "site_themes_scope_check"
  CHECK (("scope" = 'GROUP' AND "property_id" IS NULL) OR ("scope" = 'PROPERTY' AND "property_id" IS NOT NULL));
ALTER TABLE "site_assets" ADD CONSTRAINT "site_assets_kind_check" CHECK ("kind" IN ('logo', 'favicon', 'image'));
ALTER TABLE "form_uploads" ADD CONSTRAINT "form_uploads_status_check" CHECK ("status" IN ('TEMP', 'ATTACHED', 'DELETED'));
ALTER TABLE "reservation_extras" ADD CONSTRAINT "reservation_extras_status_check" CHECK ("status" IN ('ACTIVE', 'CANCELLED'));
ALTER TABLE "reservation_extras" ADD CONSTRAINT "reservation_extras_source_check" CHECK ("source" IN ('ONLINE', 'FRONT_DESK'));
ALTER TABLE "transfers" ADD CONSTRAINT "transfers_source_check" CHECK ("source" IN ('ONLINE', 'FRONT_DESK'));
ALTER TABLE "extras" ADD CONSTRAINT "extras_price_check" CHECK ("price_kobo" > 0 AND ("max_units" IS NULL OR "max_units" BETWEEN 1 AND 50));
ALTER TABLE "pickup_points" ADD CONSTRAINT "pickup_points_price_check" CHECK ("price_kobo" >= 0 AND ("drop_off_price_kobo" IS NULL OR "drop_off_price_kobo" >= 0));
-- At most one live arrival pickup and one live departure drop-off per reservation.
CREATE UNIQUE INDEX "transfers_one_live_per_direction" ON "transfers" ("reservation_id", "direction") WHERE "status" NOT IN ('CANCELLED', 'NO_SHOW');
CREATE INDEX "reservations_form_version_idx" ON "reservations" ("form_version_id") WHERE "form_version_id" IS NOT NULL;

-- Published booking form versions are immutable: reservations point at them.
CREATE OR REPLACE FUNCTION booking_form_versions_block_update() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'booking_form_versions are immutable once published: % is not allowed', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$$;
CREATE TRIGGER booking_form_versions_immutable
  BEFORE UPDATE ON booking_form_versions
  FOR EACH ROW EXECUTE FUNCTION booking_form_versions_block_update();
-- Published theme versions: never changed (old ones are pruned by DELETE).
CREATE TRIGGER site_theme_versions_immutable
  BEFORE UPDATE ON site_theme_versions
  FOR EACH ROW EXECUTE FUNCTION booking_form_versions_block_update();

-- -----------------------------------------------------------------------------
-- RLS on the new tenant tables (data plane: they move with a dedicated database).
-- -----------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'site_themes', 'site_theme_versions', 'site_assets', 'booking_forms', 'booking_form_versions', 'form_uploads',
    'extras', 'pickup_points', 'local_transport_companies', 'reservation_extras', 'transfers', 'setup_progress'
  ]
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO hotel_app
         USING (tenant_id = (SELECT app_current_tenant_id()))
         WITH CHECK (tenant_id = (SELECT app_current_tenant_id()))', t);
    EXECUTE format(
      'CREATE POLICY platform_access ON %I FOR ALL TO hotel_platform
         USING (true) WITH CHECK (true)', t);
  END LOOP;

  -- Platform catalogues (no tenant): readable by everyone, written by the seed / console only.
  FOREACH t IN ARRAY ARRAY['transport_companies', 'train_routes']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY read_all ON %I FOR SELECT USING (true)', t);
    EXECUTE format(
      'CREATE POLICY platform_access ON %I FOR ALL TO hotel_platform
         USING (true) WITH CHECK (true)', t);
  END LOOP;
END
$$;

-- -----------------------------------------------------------------------------
-- Grants.
-- -----------------------------------------------------------------------------
GRANT SELECT, INSERT, UPDATE, DELETE ON
  site_themes, site_assets, booking_forms, form_uploads, extras, pickup_points,
  local_transport_companies, reservation_extras, transfers, setup_progress
TO hotel_app;
-- Versions: written once, pruned (themes) by the API; never updated.
GRANT SELECT, INSERT, DELETE ON site_theme_versions TO hotel_app;
GRANT SELECT, INSERT ON booking_form_versions TO hotel_app;
GRANT SELECT ON transport_companies, train_routes TO hotel_app;

GRANT SELECT, INSERT, UPDATE, DELETE ON
  site_themes, site_theme_versions, site_assets, booking_forms, booking_form_versions, form_uploads,
  extras, pickup_points, local_transport_companies, reservation_extras, transfers, setup_progress,
  transport_companies, train_routes
TO hotel_platform;

