INSERT INTO features (code, name, description, category) VALUES
  ('brand_kit', 'Brand kit', 'Your logo, favicon and colours on your booking site, emails and invoices.', 'Growth'),
  ('site_templates_all', 'All booking-site templates', 'Choose from every booking-site template (Starter: Essentials and Editorial).', 'Growth'),
  ('site_sections', 'Section editor', 'Show, hide and reorder booking-site sections and choose light or dark.', 'Growth'),
  ('site_fonts', 'Font pairings', 'Choose the typefaces of your booking site from curated pairings.', 'Growth'),
  ('form_fields_unlimited', 'Unlimited form fields', 'Ask guests as many extra questions as you need when they book.', 'Guests'),
  ('form_conditional_logic', 'Conditional questions', 'Show booking-form questions only when an earlier answer calls for them.', 'Guests'),
  ('paid_extras', 'Paid extras and pickups', 'Sell breakfast, early check-in, celebrations and airport or motor-park pickups with the room.', 'Revenue'),
  ('form_file_uploads', 'File uploads in the booking form', 'Let guests attach documents such as an event invitation or a company letter.', 'Guests')
ON CONFLICT (code) DO NOTHING;

-- Plan features: brand_kit on every plan (it replaces Growth's booking_site_branding for logo and colours).
INSERT INTO plan_features (plan_id, feature_code)
SELECT p.id, f.code
FROM plans p
JOIN (VALUES
  ('starter', 'brand_kit'),
  ('growth', 'brand_kit'), ('growth', 'site_templates_all'), ('growth', 'site_sections'), ('growth', 'form_fields_unlimited'),
  ('growth', 'form_conditional_logic'), ('growth', 'paid_extras'),
  ('pro', 'brand_kit'), ('pro', 'site_templates_all'), ('pro', 'site_sections'), ('pro', 'site_fonts'), ('pro', 'form_fields_unlimited'),
  ('pro', 'form_conditional_logic'), ('pro', 'paid_extras'), ('pro', 'form_file_uploads'),
  ('enterprise', 'brand_kit'), ('enterprise', 'site_templates_all'), ('enterprise', 'site_sections'), ('enterprise', 'site_fonts'),
  ('enterprise', 'form_fields_unlimited'), ('enterprise', 'form_conditional_logic'), ('enterprise', 'paid_extras'),
  ('enterprise', 'form_file_uploads')
) AS f(plan_code, code) ON f.plan_code = p.code
WHERE EXISTS (SELECT 1 FROM features WHERE features.code = f.code)
ON CONFLICT DO NOTHING;

-- Limit: extra (library + custom) form fields. Starter 3, everyone else unlimited.
UPDATE plans SET limits = limits || jsonb_build_object('max_custom_form_fields', CASE WHEN code = 'starter' THEN 3 ELSE -1 END)
WHERE NOT (limits ? 'max_custom_form_fields');

-- booking_site_branding is now an alias of brand_kit: carry add-on / removal overrides over.
INSERT INTO tenant_feature_overrides (id, tenant_id, feature_code, enabled, note, created_at, updated_at)
SELECT gen_random_uuid(), o.tenant_id, 'brand_kit', o.enabled, COALESCE(o.note, 'Copied from booking_site_branding (M7 alias)'), now(), now()
FROM tenant_feature_overrides o
WHERE o.feature_code = 'booking_site_branding'
  AND EXISTS (SELECT 1 FROM features WHERE code = 'brand_kit')
ON CONFLICT (tenant_id, feature_code) DO NOTHING;

-- Every existing property gets a published Editorial theme from its M1 accent colour and logo
-- (sections null = the template's defaults; applied colours are computed by the API on first read).
WITH src AS (
  SELECT p.id AS property_id, p.tenant_id, gen_random_uuid() AS theme_id, gen_random_uuid() AS version_id,
         jsonb_build_object(
           'templateId', 'editorial',
           'brand', jsonb_build_object(
             'logoAssetId', NULL, 'faviconAssetId', NULL, 'logoUrl', p.logo_url, 'faviconUrl', NULL,
             'primary', CASE WHEN p.accent_color ~ '^#[0-9A-Fa-f]{6}$' THEN upper(p.accent_color) ELSE '#B4452A' END,
             'secondary', NULL, 'fontPairingId', NULL),
           'colourMode', 'SYSTEM',
           'sections', NULL
         ) AS content
  FROM properties p
  WHERE NOT EXISTS (SELECT 1 FROM site_themes t WHERE t.property_id = p.id)
), themes AS (
  INSERT INTO site_themes (id, tenant_id, property_id, scope, draft, draft_updated_at, published_version_id, created_at, updated_at)
  SELECT theme_id, tenant_id, property_id, 'PROPERTY', content, now(), version_id, now(), now() FROM src
  RETURNING id
)
INSERT INTO site_theme_versions (id, tenant_id, theme_id, version, content, note, published_at, published_by_name)
SELECT version_id, tenant_id, theme_id, 1, content, 'Created from the hotel profile (M7 migration)', now(), 'System'
FROM src WHERE theme_id IN (SELECT id FROM themes);

-- Hotels that existed before M7 have finished setting up.
INSERT INTO setup_progress (id, tenant_id, property_id, steps, started_at, completed_at, created_at, updated_at)
SELECT gen_random_uuid(), p.tenant_id, p.id, '{}'::jsonb, p.created_at, now(), now(), now()
FROM properties p
WHERE NOT EXISTS (SELECT 1 FROM setup_progress s WHERE s.property_id = p.id);
